UPDATE ip_grade_rule_alert
SET alert_status = '20'
    , context_key = #{contextKey}
    , deal_user_id = #{dealUserId}
    , deal_user_name = #{dealUserName}
    , deal_time = NOW()
    , updt_time = NOW()
WHERE id = #{id} AND rule_type = 'absCompanySync' AND is_deleted = 0

UPDATE ip_grade_rule_alert
SET issuer_code = #{issuerCode}
    , issuer_name = #{issuerName}
    , fail_reason = #{failReason}
    , alert_status = '20'
    , context_key = #{contextKey}
    , deal_user_id = #{dealUserId}
    , deal_user_name = #{dealUserName}
    , deal_time = NOW()
    , updt_time = NOW()
WHERE id = #{id}
  AND rule_type = 'absCompanySync'
  AND alert_status = '00'
  AND is_deleted = 0
